@AbapCatalog.sqlViewName: 'ZEMPLOYEE_CDS'
@AbapCatalog.compiler.compareWithVersion: '750'
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'Employee Data for OData'
@OData.publish: true
DEFINE VIEW z_employee_odata_v
  AS SELECT FROM sflights AS EmployeeData
    ASSOCIATION TO scarr AS _Department ON EmployeeData.carrid = _Department.carrid
  {
    key EmployeeData.carrid   AS DepartmentId,
    key EmployeeData.connid   AS EmployeeId,
        EmployeeData.fldate   AS HireDate,
        EmployeeData.price    AS Salary,
        EmployeeData.currency AS SalaryCurrency,

        _Department
  }

@AbapCatalog.sqlViewName: 'ZAVGFLIGHTPRICE'
@AbapCatalog.compiler.compareWithVersion: '1.0.0'
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'Average Flight Price by Carrier'
DEFINE VIEW zcds_avg_flight_price AS SELECT FROM sflight
{
  key carrid,
  avg( price ) as average_price
}
GROUP BY carrid;

CLASS zcl_syst_full_report DEFINITION PUBLIC FINAL CREATE PUBLIC.
  PUBLIC SECTION.
    METHODS get_full_system_report
      RETURNING
        VALUE(rv_report) TYPE string.
ENDCLASS.

CLASS zcl_syst_full_report IMPLEMENTATION.
  METHOD get_full_system_report.
    rv_report = |
      System Report:
      ----------------------------------------
      User:        { cl_abap_syst=>get_uname( ) }
      Date:        { cl_abap_syst=>get_datum( ) DATE = USER }
      Time:        { cl_abap_syst=>get_uzeit( ) TIME = USER }
      Program:     { cl_abap_syst=>get_repid( ) }
      Client:      { cl_abap_syst=>get_mandt( ) }
      System ID:   { cl_abap_syst=>get_sysid( ) }
      Host:        { cl_abap_syst=>get_host( ) }
      Language:    { cl_abap_syst=>get_langu( ) }
      Time Zone:   { cl_abap_syst=>get_tzone( ) }
      ----------------------------------------
    |.
  ENDMETHOD.
ENDCLASS.
